using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;
namespace Underwater.Editor {
public static class MorayPCRepair {
 const string Scene="Assets/Scenes/Underwater_Realistic.unity",Folder="Assets/UnderwaterArt/CurledMorayEncounter/";
 public static void Fix(){
 AssetDatabase.Refresh();EditorSceneManager.OpenScene(Scene);var b=UnityEngine.Object.FindFirstObjectByType<CurledMorayEncounter>();if(!b)throw new Exception("Curled moray is missing");
 var clips=AssetDatabase.LoadAllAssetsAtPath(Folder+"CurledMoray.fbx").OfType<AnimationClip>().Where(c=>!c.name.StartsWith("__")).ToArray();b.restClip=clips.Single(c=>c.name=="CurledRest");b.swimClip=clips.Single(c=>c.name=="SwimStraight");b.animationPlayer.AddClip(b.restClip,b.restClip.name);b.animationPlayer.AddClip(b.swimClip,b.swimClip.name);b.animationPlayer.clip=b.restClip;
 var mat=b.skin.sharedMaterial;mat.SetFloat("_Glossiness",.08f);mat.SetFloat("_BumpScale",.25f);mat.SetFloat("_SpecularHighlights",0);mat.SetFloat("_GlossyReflections",0);mat.EnableKeyword("_SPECULARHIGHLIGHTS_OFF");mat.EnableKeyword("_GLOSSYREFLECTIONS_OFF");b.skin.reflectionProbeUsage=ReflectionProbeUsage.Off;EditorUtility.SetDirty(mat);
 var root=b.transform;var bones=b.skin.bones;bool first=true,localFirst=true;Bounds rest=default,travel=default,local=default;var restRot=new Quaternion[bones.Length];
 for(int phase=0;phase<16;phase++){b.restClip.SampleAnimation(b.animationPlayer.gameObject,phase*.25f);var points=OctopusRepairValidation.Points(b.skin);var rb=new Bounds(root.InverseTransformPoint(points[0]),Vector3.zero);foreach(var p in points)rb.Encapsulate(root.InverseTransformPoint(p));if(first){rest=rb;travel=rb;first=false;}else rest.Encapsulate(rb);for(int i=0;i<bones.Length;i++)restRot[i]=bones[i].localRotation;b.swimClip.SampleAnimation(b.animationPlayer.gameObject,phase*.25f);var swimRot=bones.Select(t=>t.localRotation).ToArray();for(int blend=0;blend<=12;blend++){for(int i=0;i<bones.Length;i++)bones[i].localRotation=Quaternion.Slerp(restRot[i],swimRot[i],blend/12f);foreach(var p in OctopusRepairValidation.Points(b.skin)){travel.Encapsulate(root.InverseTransformPoint(p));var v=(b.skin.rootBone?b.skin.rootBone:b.skin.transform).InverseTransformPoint(p);if(localFirst){local=new Bounds(v,Vector3.zero);localFirst=false;}else local.Encapsulate(v);}}}
 rest.Expand(.016f);travel.Expand(.025f);local.Expand(.03f);b.restBounds=rest;b.travelBounds=travel;b.skin.localBounds=local;b.restClip.SampleAnimation(b.animationPlayer.gameObject,0);var guard=b.GetComponent<ReefAnimalClearance>();guard.animatedBody=rest;b.GetComponent<ReefSphereBody>().centerOffset=rest.center;root.position=guard.ConstrainPosition(root.position);Physics.SyncTransforms();b.Initialize();if(!b.CanEscape(root.position+root.forward*.5f))throw new Exception("Refined idle blocks original route: "+b.LastPlanFailure);
 AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),Scene);CurledMorayIntegration.Validate();CurledMorayIntegration.ValidateEdges();CurledMorayIntegration.Capture();Debug.Log("MORAY_PC_REPAIR_SAVED");
 }
}
}
